package com.alan.clients.module.impl.exploit.disabler;

import com.alan.clients.event.Listener;
import com.alan.clients.event.annotations.EventLink;
import com.alan.clients.event.impl.motion.StrafeEvent;
import com.alan.clients.module.impl.exploit.Disabler;
import com.alan.clients.util.packet.PacketUtil;
import com.alan.clients.value.Mode;
import net.minecraft.entity.player.PlayerCapabilities;
import net.minecraft.network.play.client.C13PacketPlayerAbilities;

public class AbilitiesDisabler extends Mode<Disabler> {
    public AbilitiesDisabler(String name, Disabler parent) {
        super(name, parent);
    }

    @EventLink
    public final Listener<StrafeEvent> onStrafe = event -> {
        if (!getParent().deprecated.getValue()) {
            return;
        }

        if (mc.thePlayer.ticksExisted % 5 == 0) {
            final PlayerCapabilities playerCapabilities = new PlayerCapabilities();
            playerCapabilities.isFlying = true;
            PacketUtil.send(new C13PacketPlayerAbilities(playerCapabilities));
        }
    };
}
// NOTE (AI): AbilitiesDisabler is a Mode of the Rise 6.x Disabler. Every 5 ticks on StrafeEvent it sends a C13 with a fresh PlayerCapabilities whose isFlying is true. The default constructor of PlayerCapabilities leaves allowFlying false, so the vanilla handler ANDs the flying bit out; the spam is aimed at anti-cheat layers that fingerprint the packet stream rather than the server state. It only runs while the parent Disabler's deprecated setting is enabled.

